(()=>{const d=document,b=document.body,h=d.querySelector('.nytt01-site-header'),m=d.querySelector('[data-nytt01-navigation]'),t=d.querySelector('[data-nytt01-menu-toggle]'),backdropClass='nytt01-menu-backdrop';const lock=s=>{b.style.overflow=s?'hidden':''};const closeAll=()=>{d.querySelectorAll('[data-nytt01-mega-panel]').forEach(p=>p.hidden=true);d.querySelectorAll('[data-menu-dropdown]').forEach(p=>p.hidden=true);d.querySelectorAll('[data-menu-item]').forEach(btn=>btn.setAttribute('aria-expanded','false'));d.querySelectorAll('[data-nytt01-mega-trigger]').forEach(btn=>btn.setAttribute('aria-expanded','false'));const mb=d.querySelector('.'+backdropClass);if(mb)mb.remove();lock(false)};const openPanel=id=>{closeAll();const p=d.getElementById(id);if(!p)return;p.hidden=false;const btn=d.querySelector(`[aria-controls="${id}"]`);if(btn)btn.setAttribute('aria-expanded','true');const bd=d.createElement('div');bd.className=backdropClass;bd.tabIndex=-1;bd.addEventListener('click',closeAll);d.body.appendChild(bd);lock(true)};d.addEventListener('click',e=>{const btn=e.target.closest('[data-nytt01-mega-trigger],[data-menu-item]');if(btn){const id=btn.getAttribute('aria-controls');const panel=d.getElementById(id);if(panel&&panel.hidden){openPanel(id)}else{closeAll()}return}if(!e.target.closest('[data-nytt01-mega-panel],[data-menu-dropdown]'))closeAll()});d.addEventListener('keydown',e=>{if(e.key==='Escape')closeAll()});if(h){const s=()=>h.classList.toggle('is-scrolled',window.scrollY>12);s();window.addEventListener('scroll',s,{passive:true})}d.querySelectorAll('[data-rail-item]').forEach(btn=>{const root=btn.closest('[data-menu-dropdown]');if(!root)return;btn.addEventListener('mouseenter',()=>{const key=btn.dataset.railItem;root.querySelectorAll('[data-rail-content]').forEach(sec=>sec.hidden=sec.dataset.railContent!==key);root.querySelectorAll('[data-rail-item]').forEach(b=>b.setAttribute('aria-pressed',b===btn?'true':'false'))});btn.addEventListener('focus',()=>btn.dispatchEvent(new Event('mouseenter')))});if(t){t.addEventListener('click',()=>{const open=t.getAttribute('aria-expanded')==='true';d.querySelector('.nytt01-mobile-drawer')?.remove();d.querySelector('.'+backdropClass)?.remove();if(open){t.setAttribute('aria-expanded','false');lock(false);return}const drawer=d.createElement('div');drawer.className='nytt01-mobile-drawer is-open';drawer.innerHTML=`<button class="btn btn-secondary btn-small" type="button" data-drawer-close>Close</button><nav class="nytt01-mobile-nav"><a class="btn btn-header-cta" href="/contact/">Contact Us</a></nav>`;d.body.appendChild(drawer);const bd=d.createElement('div');bd.className=backdropClass;bd.addEventListener('click',()=>{drawer.remove();bd.remove();lock(false);t.setAttribute('aria-expanded','false')});d.body.appendChild(bd);t.setAttribute('aria-expanded','true');lock(true);drawer.querySelector('[data-drawer-close]')?.addEventListener('click',()=>{drawer.remove();bd.remove();lock(false);t.setAttribute('aria-expanded','false')})})}d.querySelectorAll('[data-filter-group]').forEach(group=>{const cards=[...d.querySelectorAll('[data-filter-card]')];group.addEventListener('click',e=>{const btn=e.target.closest('[data-filter-value]');if(!btn)return;const value=btn.dataset.filterValue;group.querySelectorAll('[data-filter-value]').forEach(b=>b.setAttribute('aria-pressed',b===btn?'true':'false'));cards.forEach(card=>card.hidden=value!=='all'&&card.dataset.filterCard!==value)})})})();
